"""The image and the lock are two descriptions of one environment. Nothing enforces that.

A drifted image is worse than a broken one. A broken image fails; a drifted image runs,
produces numbers, and records a lock hash that truthfully describes a file which no longer
describes the container that produced them.
"""

from __future__ import annotations

from nas4textgen.audit_image import audit, canonical, parse_lock

LOCK = """\
# This file was autogenerated by uv
--index-url https://pypi.org/simple

numpy==2.1.0
torch==2.4.1
    # via nas4textgen
Pillow==10.4.0
transformers==4.44.2 ; python_version >= "3.12"
"""


def test_lock_parsing_ignores_everything_that_is_not_a_pin():
    pinned = parse_lock(LOCK)
    assert pinned == {
        "numpy": "2.1.0",
        "torch": "2.4.1",
        "pillow": "10.4.0",
        "transformers": "4.44.2",
    }


def test_names_are_compared_after_normalisation():
    """Pillow, pillow and PIL_low are one distribution; a naive compare reports drift."""
    assert canonical("Pillow") == canonical("pillow") == "pillow"
    assert canonical("ruamel.yaml") == canonical("ruamel-yaml") == "ruamel-yaml"

    assert audit(LOCK, {"numpy": "2.1.0", "torch": "2.4.1",
                        "Pillow": "10.4.0", "transformers": "4.44.2"}) != []
    assert audit(LOCK, {canonical(k): v for k, v in
                        {"numpy": "2.1.0", "torch": "2.4.1",
                         "Pillow": "10.4.0", "transformers": "4.44.2"}.items()}) == []


def test_a_different_version_is_drift():
    problems = audit(LOCK, {"numpy": "2.1.0", "torch": "2.5.0",
                            "pillow": "10.4.0", "transformers": "4.44.2"})
    assert any("torch is 2.5.0" in p for p in problems)


def test_a_missing_package_is_drift():
    problems = audit(LOCK, {"numpy": "2.1.0", "pillow": "10.4.0",
                            "transformers": "4.44.2"})
    assert any("torch" in p and "not installed" in p for p in problems)


def test_an_unlocked_package_is_drift_even_when_every_pin_matches():
    """The direction that is easy to forget.

    A package present but unlocked entered the image some way the lock does not describe.
    Every pinned version can match and the lock still fails to reproduce the container.
    """
    problems = audit(LOCK, {"numpy": "2.1.0", "torch": "2.4.1", "pillow": "10.4.0",
                            "transformers": "4.44.2", "requests": "2.32.3"})
    assert any("requests" in p and "absent from the lock" in p for p in problems)


def test_build_tooling_is_not_reported():
    """pip and the project itself are installed by the build, not by the lock."""
    assert audit(LOCK, {"numpy": "2.1.0", "torch": "2.4.1", "pillow": "10.4.0",
                        "transformers": "4.44.2", "pip": "24.2",
                        "nas4textgen": "0.1.0"}) == []


def test_only_pip_installed_distributions_are_audited():
    """Operating-system packages are not pip's to pin, and no lock will ever name them.

    The CUDA base image carries nineteen — python-apt, dbus-python, pygobject — that apt
    pulled in as dependencies of the tooling that installs Python 3.12 itself. Counting
    them as drift makes the check permanently red, and a check that is always red is a
    check nobody reads.

    The first attempt excluded anything under "dist-packages", which on Debian is where
    pip installs too, so it reported zero installed distributions and flagged the entire
    lock as missing. Asking sysconfig where pip installs for *this* interpreter is what
    actually separates the two, and it works unchanged in a venv, on macOS and on Windows.
    """
    from nas4textgen.audit_image import _install_roots, installed_distributions

    roots = _install_roots()
    assert roots, "sysconfig must name at least one install location"
    assert all(root for root in roots)

    found = installed_distributions()
    assert found, "the running environment has pip-installed packages; none were seen"
    # This project itself is always installed by pip into one of those roots.
    assert "nas4textgen" in found
